root=Path(__file__).resolve().parents[1]
put("common/settings.h","#pragma once\n")
put("citra_libretro/environment.h","#pragma once\n#include <cstddef>\nnamespace LibRetro {bool ToolRingVisible();int ToolRingSelected();void RenderToolRing(int,int,void*,size_t);}\n")
put("video_core/texture/texture_decode.h","#pragma once\n#include <cstddef>\n#include \"common/common_types.h\"\nnamespace Pica {struct TexturingRegs {enum class TextureFormat {ETC1A4};};namespace Texture {struct TextureInfo {u32 width{},height{};TexturingRegs::TextureFormat format{};void SetDefaultStride(){}};struct Color {u8 r()const{return 0;}u8 g()const{return 0;}u8 b()const{return 0;}u8 a()const{return 0;}};inline Color LookupTexture(const u8*,unsigned,unsigned,const TextureInfo&){return {};}}}\n")
env=(root/"src/citra_libretro/environment.cpp").read_text()
ui_start=env.index("namespace {\nbool tool_ring_open")
ui=env[ui_start:env.index("bool GetSensorInterface",ui_start)]
